import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"Control Plane and Autonomy","description":"Triggers, Policies, Mandates, scheduling, Watchdog, attention budget, and proactive loops in the Hearth Control Plane.","frontmatter":{"title":"Control Plane and Autonomy","description":"Triggers, Policies, Mandates, scheduling, Watchdog, attention budget, and proactive loops in the Hearth Control Plane.","outline":[2,3]},"headers":[],"relativePath":"en/architecture/control-plane.md","filePath":"en/architecture/control-plane.md","lastUpdated":1793706118000}'),o={name:"en/architecture/control-plane.md"};function l(r,e,s,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[i(`<p class="eyebrow">CONTROL PLANE</p><h1 id="control-plane-and-autonomy" tabindex="-1">Control Plane and Autonomy <a class="header-anchor" href="#control-plane-and-autonomy" aria-label="Permalink to &quot;Control Plane and Autonomy&quot;">​</a></h1><p class="lead">Who decides what to do, whether it is allowed, when to interrupt, and when to pause. The Control Plane is not an executor; it is the judgment layer for tasks and authorization.</p><h2 id="control-plane-and-autonomy-1" tabindex="-1">Control Plane and Autonomy <a class="header-anchor" href="#control-plane-and-autonomy-1" aria-label="Permalink to &quot;Control Plane and Autonomy&quot;">​</a></h2><p>The Control Plane decides:</p><ul><li>whether an event is worth processing;</li><li>whether to create a Task;</li><li>whether user approval is required;</li><li>which Executor to apply;</li><li>how many Tokens, how much time, and how much money to spend;</li><li>when to notify and when to stay silent;</li><li>after a failure, whether to retry, switch paths, or escalate to a human.</li></ul><p>It does not directly call tools, does not directly hold credentials, and does not directly write to external services.</p><h3 id="trigger" tabindex="-1">Trigger <a class="header-anchor" href="#trigger" aria-label="Permalink to &quot;Trigger&quot;">​</a></h3><p>A Trigger is a combination of rules, subscriptions, and conditions: cron, file changes, web page changes, email arrival, upcoming calendar events, GitHub Issue/PR, device online/offline, task dependency completion, explicit user subscriptions, and failure retries.</p><p>Rule hits can directly create a Ticket; only when semantic judgment is needed is a small model invoked. A Trigger is not &quot;having a large model observe everything all the time.&quot;</p><h3 id="policy-and-mandate" tabindex="-1">Policy and Mandate <a class="header-anchor" href="#policy-and-mandate" aria-label="Permalink to &quot;Policy and Mandate&quot;">​</a></h3><p>A Policy is a long-term rule; a Mandate is an authorization instance for a single occasion or a period of time.</p><p>A Mandate contains at least:</p><ul><li>allowed action types;</li><li>resource scope;</li><li>contact/domain/repository/folder scope;</li><li>risk level;</li><li>budget;</li><li>validity period;</li><li>whether automatic execution is allowed;</li><li>whether forwarding or delegation is allowed;</li><li>how to revoke it.</li></ul><p>The model can make suggestions, but it cannot modify a Mandate, Approval, or its own capability.</p><h3 id="scheduling-and-watchdog" tabindex="-1">Scheduling and Watchdog <a class="header-anchor" href="#scheduling-and-watchdog" aria-label="Permalink to &quot;Scheduling and Watchdog&quot;">​</a></h3><p>The scheduler is responsible for priority, concurrency limits, device/Executor matching, budget, deadlines, dependency waiting, and fairness.</p><p>The Watchdog runs independently of the Agent and is responsible for:</p><ul><li>stuck detection;</li><li>infinite loop detection;</li><li>budget overruns;</li><li>device disconnection;</li><li>credential expiration;</li><li>external platform anomalies;</li><li>automatic degradation or escalation to a human.</li></ul><p>The Watchdog is not another model, but a set of deterministic supervision mechanisms.</p><h3 id="the-correct-boundaries-of-autonomy" tabindex="-1">The Correct Boundaries of Autonomy <a class="header-anchor" href="#the-correct-boundaries-of-autonomy" aria-label="Permalink to &quot;The Correct Boundaries of Autonomy&quot;">​</a></h3><p>Autonomy is not &quot;the model does whatever it wants,&quot; but rather:</p><ul><li>autonomy within an explicit Mandate;</li><li>autonomy within budget;</li><li>autonomy within a recoverable/rollback-able scope;</li><li>autonomy in low-risk scenarios;</li><li>high-risk actions always retain human confirmation.</li></ul><h3 id="attention-budget" tabindex="-1">Attention Budget <a class="header-anchor" href="#attention-budget" aria-label="Permalink to &quot;Attention Budget&quot;">​</a></h3><p>Every task has an attention budget, not just a Token budget:</p><ul><li>maximum number of interruptions;</li><li>aggregation window;</li><li>quiet hours;</li><li>default action;</li><li>escalation conditions;</li><li>behavior after the user disables a channel.</li></ul><p>Rules:</p><ul><li>anything that can be verified automatically does not require human confirmation;</li><li>anything that can safely wait does not interrupt immediately;</li><li>anything that can be approved in batch does not interrupt item by item;</li><li>every interruption must have one clear action;</li><li>if the same task is interrupted more than 2 times and the count cannot be reduced, fall back to &quot;suggest only, do not execute.&quot;</li></ul><h3 id="proactive-loop" tabindex="-1">Proactive Loop <a class="header-anchor" href="#proactive-loop" aria-label="Permalink to &quot;Proactive Loop&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Source Event</span></span>
<span class="line"><span>  → Trigger / Rule</span></span>
<span class="line"><span>  → Small classifier</span></span>
<span class="line"><span>  → Task / Thread</span></span>
<span class="line"><span>  → Policy + Mandate</span></span>
<span class="line"><span>  → Budget</span></span>
<span class="line"><span>  → Executor</span></span>
<span class="line"><span>  → Verification</span></span>
<span class="line"><span>  → Notification / Receipt</span></span></code></pre></div><p>Active mode and suggestion mode must be independently toggleable and backed by comparative data. The real proactive loop is not enabled before Phase 4.</p>`,31)])])}const m=a(o,[["render",l]]);export{u as __pageData,m as default};
